function longestSliceWithSum(nums: number[], k: number): number {
  const first = new Map<number, number>([[0, -1]]);
  let sum = 0, best = 0;
  for (let j = 0; j < nums.length; j++) {
    sum += nums[j];
    const i = first.get(sum - k);
    if (i !== undefined) best = Math.max(best, j - i);
    if (!first.has(sum)) first.set(sum, j);
  }
  return best;
}

